--
-- Estructura de tabla para la tabla `evaluations`
--

CREATE TABLE `evaluations` (
  `id` int(11) NOT NULL,
  `title` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `bimestre` varchar(2) NOT NULL COMMENT 'Número de bimestre (1-4)',
  `teacher_id` int(11) NOT NULL,
  `teacher_course_id` int(11) NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `type` varchar(50) NOT NULL DEFAULT 'Examen',
  `academic_year_id` int(11) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'Activa',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `annulled_at` datetime DEFAULT NULL,
  `annulled_by` int(11) DEFAULT NULL,
  `annulment_reason` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_spanish2_ci;

--
-- Volcado de datos para la tabla `evaluations`
--


--
-- Disparadores `evaluations`
--
DELIMITER $$
CREATE TRIGGER `trg_grade_close_eval_delete` BEFORE DELETE ON `evaluations` FOR EACH ROW BEGIN
    IF EXISTS (
        SELECT 1 FROM grade_period_closures gpc
        WHERE gpc.teacher_course_id = OLD.teacher_course_id
          AND gpc.bimester = CAST(OLD.bimestre AS UNSIGNED)
          AND gpc.status = 'Cerrado'
        LIMIT 1
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El bimestre está cerrado. No se puede eliminar ni anular una evaluación.';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_grade_close_eval_insert` BEFORE INSERT ON `evaluations` FOR EACH ROW BEGIN
    IF EXISTS (
        SELECT 1 FROM grade_period_closures gpc
        INNER JOIN teacher_courses tc ON tc.id = NEW.teacher_course_id AND tc.school_id = gpc.school_id
        WHERE gpc.teacher_course_id = NEW.teacher_course_id
          AND gpc.bimester = CAST(NEW.bimestre AS UNSIGNED)
          AND gpc.status = 'Cerrado'
        LIMIT 1
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El bimestre está cerrado. Solicite una reapertura antes de crear evaluaciones.';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_grade_close_eval_update` BEFORE UPDATE ON `evaluations` FOR EACH ROW BEGIN
    IF EXISTS (
        SELECT 1 FROM grade_period_closures gpc
        WHERE gpc.teacher_course_id = OLD.teacher_course_id
          AND gpc.bimester = CAST(OLD.bimestre AS UNSIGNED)
          AND gpc.status = 'Cerrado'
        LIMIT 1
    ) OR EXISTS (
        SELECT 1 FROM grade_period_closures gpc
        WHERE gpc.teacher_course_id = NEW.teacher_course_id
          AND gpc.bimester = CAST(NEW.bimestre AS UNSIGNED)
          AND gpc.status = 'Cerrado'
        LIMIT 1
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El bimestre está cerrado. Solicite una reapertura antes de modificar evaluaciones.';
    END IF;
END
$$
DELIMITER ;

