--


--
-- Disparadores `evaluation_grades`
--
DELIMITER $$
CREATE TRIGGER `trg_grade_close_grade_delete` BEFORE DELETE ON `evaluation_grades` FOR EACH ROW BEGIN
    IF EXISTS (
        SELECT 1
        FROM evaluations e
        INNER JOIN grade_period_closures gpc
            ON gpc.teacher_course_id = e.teacher_course_id
           AND gpc.bimester = CAST(e.bimestre AS UNSIGNED)
           AND gpc.status = 'Cerrado'
        WHERE e.id = OLD.evaluation_id
        LIMIT 1
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Las notas de este bimestre están cerradas. Solicite una reapertura.';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_grade_close_grade_insert` BEFORE INSERT ON `evaluation_grades` FOR EACH ROW BEGIN
    IF EXISTS (
        SELECT 1
        FROM evaluations e
        INNER JOIN grade_period_closures gpc
            ON gpc.teacher_course_id = e.teacher_course_id
           AND gpc.bimester = CAST(e.bimestre AS UNSIGNED)
           AND gpc.status = 'Cerrado'
        WHERE e.id = NEW.evaluation_id
        LIMIT 1
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Las notas de este bimestre están cerradas. Solicite una reapertura.';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_grade_close_grade_update` BEFORE UPDATE ON `evaluation_grades` FOR EACH ROW BEGIN
    IF EXISTS (
        SELECT 1
        FROM evaluations e
        INNER JOIN grade_period_closures gpc
            ON gpc.teacher_course_id = e.teacher_course_id
           AND gpc.bimester = CAST(e.bimestre AS UNSIGNED)
           AND gpc.status = 'Cerrado'
        WHERE e.id IN (OLD.evaluation_id, NEW.evaluation_id)
        LIMIT 1
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Las notas de este bimestre están cerradas. Solicite una reapertura.';
    END IF;
END
$$
DELIMITER ;

